"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _dependents(changes):
    """Validate graph targets and return id -> set of dependent change IDs."""
    known = {row["id"] for row in changes}
    dependents = {row["id"]: set() for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
            dependents[dep].add(row["id"])
    return dependents


def topological_order(changes, dependents):
    """Kahn's algorithm with lexicographic ID tie-breaking."""
    pending = {row["id"]: set(row["depends_on"]) for row in changes}
    ready = [change_id for change_id, deps in pending.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for follower in dependents[change_id]:
            deps = pending[follower]
            deps.discard(change_id)
            if not deps:
                heapq.heappush(ready, follower)
    if len(order) != len(pending):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        dependents = _dependents(changes)
        order = topological_order(changes, dependents)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    known = {row["id"] for row in changes}
    if any(change_id not in known for change_id in applied):
        return failure("unknown-dependency")
    applied_ids = set(applied)

    if request.get("action") == "rollback":
        actions = [change_id for change_id in reversed(order) if change_id in applied_ids]
    else:
        actions = [change_id for change_id in order if change_id not in applied_ids]
        units = sum(row["units"] for row in changes if row["id"] not in applied_ids)
        if units > budget:
            return failure("budget-exceeded")

    units_by_id = {row["id"]: row["units"] for row in changes}
    emitted = sum(units_by_id[change_id] for change_id in actions)
    return {"status": "ok", "actions": actions, "units": emitted}

