"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_nonempty_str(value):
    return isinstance(value, str) and value != ""


def _read_dependencies(row):
    deps = row.get("depends_on", [])
    if type(deps) is not list:
        raise JournalError("invalid-change")
    for dep in deps:
        if not _is_nonempty_str(dep):
            raise JournalError("invalid-change")
    return deps


def read_applied(records):
    """Return the persisted release journal as an ordered list of change IDs."""
    if type(records) is not list:
        raise JournalError("invalid-change")
    for entry in records:
        if not _is_nonempty_str(entry):
            raise JournalError("invalid-change")
    return list(records)


def read_retain(records):
    """Return the rollback retain list as an ordered list of change IDs.

    Only the shape is checked here; whether each ID is applied is settled
    once the persisted journal is known.
    """
    if type(records) is not list:
        raise JournalError("invalid-retain")
    for entry in records:
        if not _is_nonempty_str(entry):
            raise JournalError("invalid-retain")
    return list(records)


def retain_set(retain, applied, changes):
    """Return the IDs a rollback must leave applied.

    Each retain entry must already be applied, otherwise ``invalid-retain``
    is raised. The result is the requested IDs plus every transitive
    dependency of theirs that is itself applied. The graph is known to be
    acyclic by the time this runs, so the closure terminates.
    """
    applied_ids = set(applied)
    for change_id in retain:
        if change_id not in applied_ids:
            raise JournalError("invalid-retain")
    dependencies = {row["id"]: set(row["depends_on"]) for row in changes}
    retained = set()
    stack = list(retain)
    while stack:
        change_id = stack.pop()
        if change_id in retained:
            continue
        retained.add(change_id)
        for dep in dependencies[change_id]:
            if dep in applied_ids:
                stack.append(dep)
    return retained


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Duplicates whose ID, component and units agree but whose dependency sets
    conflict raise ``conflicting-change``.
    """
    if type(records) is not list:
        raise JournalError("invalid-change")
    by_id = {}
    order = []
    for row in records:
        if (not isinstance(row, dict) or not _is_nonempty_str(row.get("id"))
                or not _is_nonempty_str(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row),
        }
        prior = by_id.get(change["id"])
        if prior is None:
            by_id[change["id"]] = change
            order.append(change["id"])
            continue
        if (prior["component"] != change["component"]
                or prior["units"] != change["units"]
                or set(prior["depends_on"]) != set(change["depends_on"])):
            raise JournalError("conflicting-change")
    return [by_id[change_id] for change_id in order]

