"""Normalize release records at the input boundary.

This module owns input validation, change identity and replay state. It is the
only place that decides what a change record is, so policy can account units
and planner can build graphs from already-clean, already-deduplicated data. It
imports no other project module; planner imports it.
"""


class JournalError(ValueError):
    pass


def _id_list(value, code):
    """Read an optional array of change IDs, rejecting anything malformed.

    `depends_on` and the caller-supplied `applied` journal both arrive as lists
    of IDs. A non-array, or an element that is not a nonempty string, is broken
    input rather than a graph problem, so both raise `code`
    ("invalid-change"). Duplicates inside the list carry no meaning and are
    collapsed so membership tests against `applied` stay exact.
    """
    if value is None:
        return []
    if not isinstance(value, list):
        raise JournalError(code)
    seen = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError(code)
        if item not in seen:
            seen.append(item)
    return seen


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Duplicates are compared on id, component, units and the *set* of
    dependencies; order inside `depends_on` is not identity. One record per ID
    survives. Records that share an ID but differ in any of those fields are a
    conflict, not a merge: silently keeping one would change what gets
    deployed, so they fail with `conflicting-change`.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        deps = sorted(_id_list(row.get("depends_on"), "invalid-change"))
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": deps,
        }
        previous = changes.get(change["id"])
        if previous is None:
            changes[change["id"]] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(value):
    """Read the persisted release journal (`applied`) supplied by the caller.

    Membership in this list is what makes a change already deployed for replay;
    membership tests therefore live with the rest of the identity data here.
    """
    return _id_list(value, "invalid-change")

planner.py.text:
"""Compose policy and journal data into a plan.

Planner is the only module that sees the whole request: it asks journal for
clean records and the applied journal, asks policy for the action and budget,
builds the graph and emits one exact result. Every failure returns the shared
error shape, so no caller can observe a partial action list.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def ordered_ids(changes, applied):
    """Return the full deterministic topological order of all change IDs.

    Dependencies that are already applied do not hold a change back: replay
    means the persisted journal satisfies them. Ties among currently eligible
    changes are broken by lexicographic ID so the same request always yields
    the same order. If anything never becomes eligible a cycle exists;
    reporting it here keeps plan and rollback consistent, because rollback
    needs the full order even though it emits only a subset.
    """
    remaining = {change["id"]: set(change["depends_on"]) for change in changes}
    applied_set = set(applied)
    pending = {
        change_id: {dep for dep in deps if dep not in applied_set}
        for change_id, deps in remaining.items()
    }
    ready = [change_id for change_id, deps in pending.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for other in pending:
            if change_id in pending[other]:
                pending[other].discard(change_id)
                if not pending[other] and other not in order:
                    heapq.heappush(ready, other)
    if len(order) != len(pending):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        known = {change["id"] for change in changes}
        # Unknown IDs are checked before ordering: a dependency on a change that
        # was never supplied, or an applied ID that disappears from the request,
        # is a journal/data problem, not a cycle.
        for change in changes:
            if any(dep not in known for dep in change["depends_on"]):
                raise JournalError("unknown-dependency")
        if any(change_id not in known for change_id in applied):
            raise JournalError("unknown-dependency")
        order = ordered_ids(changes, applied)
        applied_set = set(applied)
        units_by_id = {change["id"]: change["units"] for change in changes}
        if action == "plan":
            actions = [change_id for change_id in order if change_id not in applied_set]
        else:
            actions = [change_id for change_id in reversed(order) if change_id in applied_set]
        units = sum(units_by_id[change_id] for change_id in actions)
        # Budget is checked against the emitted units, after replay and
        # deduplication, so already-applied changes never consume new capacity.
        check_budget(action, budget, units)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

