        for change_id, deps in remaining.items()
    }
    ready = [change_id for change_id, deps in pending.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for other in pending:
            if change_id in pending[other]:
                pending[other].discard(change_id)
                if not pending[other] and other not in order:
                    heapq.heappush(ready, other)
    if len(order) != len(pending):
        raise JournalError("dependency-cycle")
    return order


def retained_ids(changes, applied, retain):
    """Expand `retain` into the applied IDs a rollback must leave in place.

    A retained change is useless without its prerequisites, so the set is the
    *transitive* dependency closure of the retained IDs, restricted to changes
    that are actually applied: an unapplied dependency is not running and
    therefore needs no retention. Only applied changes can be emitted by
    rollback at all, so anything outside `applied` is irrelevant here.

    `retain` itself is already validated (applied membership, shape) by journal;
    this function adds only the graph walk. The closure terminates because a
    cycle was already rejected before this point.
    """
    deps_by_id = {change["id"]: change["depends_on"] for change in changes}
    applied_set = set(applied)
    kept = set()
    stack = [change_id for change_id in retain if change_id in applied_set]
    while stack:
        change_id = stack.pop()
        if change_id in kept:
            continue
        kept.add(change_id)
        stack.extend(dep for dep in deps_by_id.get(change_id, ()) if dep in applied_set)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        # `applied` (and later `retain`) default to empty only when the key is
        # absent; an explicit JSON null is passed through so journal can reject
        # it as malformed instead of silently treating it as "nothing applied".
        applied = read_applied(request.get("applied", []))
        known = {change["id"] for change in changes}
        # Unknown IDs are checked before ordering: a dependency on a change that
        # was never supplied, or an applied ID that disappears from the request,
        # is a journal/data problem, not a cycle.
        for change in changes:
            if any(dep not in known for dep in change["depends_on"]):
                raise JournalError("unknown-dependency")
        if any(change_id not in known for change_id in applied):
            raise JournalError("unknown-dependency")
        order = ordered_ids(changes, applied)
        applied_set = set(applied)
        units_by_id = {change["id"]: change["units"] for change in changes}
        if action == "plan":
            actions = [change_id for change_id in order if change_id not in applied_set]
        else:
            # G2 staging rollback: `retain` is read only here, so a plan can
            # never be influenced by it. Validation happens before the walk, and
            # kept IDs are subtracted from the reverse order rather than
            # re-sorted, so the remaining actions keep the original
            # deterministic rollback order.
            retain = read_retain(request.get("retain", []), applied)
            kept = retained_ids(changes, applied, retain)
            actions = [
                change_id for change_id in reversed(order)
                if change_id in applied_set and change_id not in kept
            ]
        units = sum(units_by_id[change_id] for change_id in actions)
        # Budget is checked against the emitted units, after replay and
        # deduplication, so already-applied changes never consume new capacity.
        check_budget(action, budget, units)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

