"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_text(value):
    return isinstance(value, str) and value != ""


def _change(row):
    """Validate one change record and return its normalized form."""
    if not isinstance(row, dict):
        raise JournalError("invalid-change")
    change_id = row.get("id")
    component = row.get("component")
    units = row.get("units")
    if not _is_text(change_id) or not _is_text(component) or type(units) is not int or units < 1:
        raise JournalError("invalid-change")
    depends_on = row.get("depends_on")
    if depends_on is None:
        depends_on = []
    if not isinstance(depends_on, list):
        raise JournalError("invalid-change")
    for target in depends_on:
        if not _is_text(target):
            raise JournalError("invalid-change")
    return {
        "id": change_id,
        "component": component,
        "units": units,
        "depends_on": frozenset(depends_on),
    }


def read_changes(records):
    """Return unique changes keyed by ID, collapsing identical duplicates."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        change = _change(row)
        key = (change["component"], change["units"], change["depends_on"])
        known = changes.get(change["id"])
        if known is None:
            changes[change["id"]] = change
        elif (known["component"], known["units"], known["depends_on"]) != key:
            raise JournalError("conflicting-change")
    return changes


def read_applied(applied):
    """Return the set of applied change IDs from the persisted release journal."""
    if applied is None:
        return set()
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    ids = set()
    for change_id in applied:
        if not _is_text(change_id):
            raise JournalError("invalid-change")
        ids.add(change_id)
    return ids

