from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Return the full deterministic order: lexicographic among eligible IDs."""
    dependents = {change_id: [] for change_id in changes}
    pending = {}
    for change_id, change in changes.items():
        for target in change["depends_on"]:
            if target not in changes:
                raise JournalError("unknown-dependency")
            dependents[target].append(change_id)
        pending[change_id] = len(change["depends_on"])
    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(changes, retain):
    """Return the retain set plus its applied transitive dependencies."""
    kept = set()
    stack = sorted(retain)
    while stack:
        change_id = stack.pop()
        if change_id in kept:
            continue
        kept.add(change_id)
        stack.extend(changes[change_id]["depends_on"])
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        action = request["action"]
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        for change_id in applied:
            if change_id not in changes:
                raise JournalError("unknown-dependency")
        order = topological_order(changes)
        retain = read_retain(request.get("retain"), applied) if action == "rollback" else set()
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if action == "rollback":
        keep = retained_closure(changes, retain)
        actions = [change_id for change_id in reversed(order) if change_id in applied and change_id not in keep]
    else:
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(changes[change_id]["units"] for change_id in actions)
    if action != "rollback" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

