"""JSON transport for the release planner."""
import json
import sys
import traceback

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError, RecursionError, UnicodeError):
        # Deeply nested or non-UTF8 input is still a transport failure: exit 0
        # with a JSON result, never a traceback (SPEC: all requests exit normally).
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        try:
